-- BEGIN 07_create_table_soap_note_grade_flag.sql
-- ========================================================================

-- Safety flags that fire independently of the completeness status, with a
-- priority and a suggested action for the clinician or governance team.

CREATE TABLE soap_note_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    soap_note_grade_id UUID NOT NULL
        REFERENCES soap_note_grade(id) ON DELETE CASCADE,

    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(50) NOT NULL DEFAULT ''
        CHECK (category IN (
            'missing-assessment',
            'missing-plan',
            'red-flag-no-plan',
            'no-safety-netting',
            'abnormal-vitals-unaddressed',
            'incomplete-documentation',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX soap_note_grade_flag_grade_id_idx
    ON soap_note_grade_flag (soap_note_grade_id);

CREATE TRIGGER trigger_soap_note_grade_flag_updated_at
    BEFORE UPDATE ON soap_note_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE soap_note_grade_flag IS
    'Safety flags that fire independently of the completeness status, with priority and a suggested action for the clinician or governance team.';
COMMENT ON COLUMN soap_note_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN soap_note_grade_flag.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN soap_note_grade_flag.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN soap_note_grade_flag.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN soap_note_grade_flag.soap_note_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN soap_note_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-MISSING-ASSESSMENT-001).';
COMMENT ON COLUMN soap_note_grade_flag.category IS
    'Flag category: missing-assessment, missing-plan, red-flag-no-plan, no-safety-netting, abnormal-vitals-unaddressed, incomplete-documentation, or other.';
COMMENT ON COLUMN soap_note_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN soap_note_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN soap_note_grade_flag.suggested_action IS
    'Suggested clinical or governance action (e.g. "record an assessment", "document safety-netting advice").';

-- ========================================================================
-- END 07_create_table_soap_note_grade_flag.sql
